<script setup lang="ts">import{CHANNEL_MODE_LABELS,type ChannelMode,type EmotionLabel,type EmotionResult}from'../../core/models';defineProps<{result:EmotionResult;channelMode:ChannelMode;modes:ChannelMode[];stale:boolean}>();const emit=defineEmits<{select:[e:EmotionLabel];next:[];updateMode:[m:ChannelMode];reanalyze:[]}>();const labels:EmotionLabel[]=['暴躁老哥','温柔姐姐','阴阳怪气','元气满满'];</script>
<template><section class="stage-card"><span class="kicker">03 / MOOD MATCH</span><h2>这段声音，有点像——</h2><div class="channel-modes"><span>分析声道</span><button v-for="mode in modes" :key="mode" type="button" :data-mode="mode" :class="{active:channelMode===mode}" :disabled="modes.length===1" @click="emit('updateMode',mode)">{{ modes.length>1?CHANNEL_MODE_LABELS[mode]:'单声道（原声道）' }}</button></div><div v-if="stale" class="stale-banner"><span>声道口径已切换，当前结果仍基于旧口径，不能代表新选择。</span><button data-testid="reanalyze" type="button" @click="emit('reanalyze')">用新口径重新分析</button></div><div class="emotion-hero"><b>{{ result.label }}</b><strong>{{ Math.round(result.confidence*100) }}%</strong><p>{{ result.explanation }}</p></div><div class="emotion-options"><button v-for="label in labels" :key="label" type="button" :data-emotion="label" :class="{active:result.label===label}" :disabled="stale" @click="emit('select',label)">{{ label }}</button></div><button data-testid="to-cover" class="acid-button" type="button" :disabled="stale" @click="emit('next')">用这个情绪做封面 →</button></section></template>
